CREATE OR REPLACE FUNCTION public.deactivate_produto(p_produto_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_company uuid; v_active boolean;
BEGIN
 v_company:=public.assert_tenant();
 IF auth.uid() IS NULL OR NOT public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:delete','estoque:cadastros:delete','estoque:cadastros:manage','stock:delete','system:global:manage']) THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
 SELECT ativo INTO v_active FROM public.produtos WHERE id=p_produto_id AND company_id=v_company FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND' USING ERRCODE='42501'; END IF;
 IF v_active THEN UPDATE public.produtos SET ativo=false WHERE id=p_produto_id AND company_id=v_company; END IF;
 RETURN p_produto_id;
END $function$

CREATE OR REPLACE FUNCTION public.generate_next_sku(p_prefix text DEFAULT 'MP'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_next bigint;
  v_pad integer;
  v_candidate text;
  v_attempts integer := 0;
  v_max_attempts integer := 1000;
BEGIN
  v_company_id := public.assert_tenant();
  -- Salmão cria seu produto internamente; mantém caller/corpo/lock da Fase 4.
  IF auth.uid() IS NULL OR NOT (public.has_any_permission(auth.uid(),ARRAY['estoque:catalogo:create','estoque:cadastros:create','estoque:cadastros:manage','stock:edit','stock:write','system:global:manage']) OR (p_prefix='SALM' AND public.has_any_permission(auth.uid(),ARRAY['salmon:entradas:create','salmon:entries:create','salmon:write','system:global:manage']))) THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
  IF p_prefix IS NULL OR length(p_prefix) NOT BETWEEN 1 AND 32 THEN RAISE EXCEPTION 'INVALID_SKU_PREFIX' USING ERRCODE='22023'; END IF;

  INSERT INTO public.stock_sku_counter (company_id, prefix, next_value, pad_length, updated_at)
  VALUES (v_company_id, p_prefix, 0, 4, now())
  ON CONFLICT (company_id, prefix) DO NOTHING;

  LOOP
    v_attempts := v_attempts + 1;
    IF v_attempts > v_max_attempts THEN
      RAISE EXCEPTION
        'generate_next_sku: nao foi possivel gerar SKU unico apos % tentativas (company=%, prefix=%)',
        v_max_attempts, v_company_id, p_prefix;
    END IF;

    UPDATE public.stock_sku_counter
       SET next_value = next_value + 1,
           updated_at = now()
     WHERE company_id = v_company_id
       AND prefix = p_prefix
    RETURNING next_value, pad_length INTO v_next, v_pad;

    v_candidate := p_prefix || '-' || lpad(v_next::text, GREATEST(COALESCE(v_pad, 4), 1), '0');

    IF NOT EXISTS (
      SELECT 1
      FROM public.produtos
      WHERE company_id = v_company_id
        AND sku = v_candidate
    ) THEN
      RETURN v_candidate;
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.produtos_force_company_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_company uuid;
BEGIN
 IF TG_OP='INSERT' THEN
  v_company:=public.assert_tenant();
  IF NEW.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION 'PRODUCT_COMPANY_MISMATCH' USING ERRCODE='42501'; END IF;
 ELSIF TG_OP='UPDATE' THEN
  IF NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'PRODUCT_COMPANY_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF current_user='authenticated' AND NEW.ativo IS DISTINCT FROM OLD.ativo AND NEW.ativo IS NOT TRUE THEN
   RAISE EXCEPTION 'USE_DEACTIVATE_PRODUTO' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END $function$
